def gap_runs(values: list[int]) -> list[tuple[int, int]]:
    """Return inclusive endpoints of maximal runs, ignoring duplicates."""
    ordered = sorted(set(values))
    if not ordered:
        return []

    runs: list[tuple[int, int]] = []
    start = end = ordered[0]

    for value in ordered[1:]:
        if value == end + 1:
            end = value
        else:
            runs.append((start, end))
            start = end = value

    runs.append((start, end))
